let config=read('river.config',{url:'https://dhhoahxdgafmjfxgnipl.supabase.co',key:'sb_publishable_SRYxZUcRnqjEGP-aSO-VOQ_OSxD-Ohp'}),session=read('river.session',null),loginRole='student',user=null,data={modules:[],lessons:[],lesson_progress:[],questions:[],comments:[],profiles:[],question_attachments:[]},page='dashboard',selectedModule=null,selectedLesson=null,selectedQuestion=null,filter='all',query='',busy=false,questionImageUrls={};
