const admin=()=>user?.role==='admin';const date=v=>new Date(v).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});const sort=rows=>[...rows].sort((a,b)=>(a.position||0)-(b.position||0));const mods=()=>sort(data.modules);const lessons=id=>sort(data.lessons.filter(l=>l.module_id===id));const progress=id=>data.lesson_progress.find(p=>p.lesson_id===id&&p.user_id===user.id);const pct=(n,d)=>d?Math.round(n/d*100):0;const moduleStats=id=>{const ls=lessons(id);return {total:ls.length,watched:ls.filter(l=>progress(l.id)?.watched).length,reviewed:ls.filter(l=>progress(l.id)?.reviewed).length}};
