async function api(path,options={}){if(!config)throw Error('Conecte seu projeto Supabase primeiro.');if(session&&session.expires_at&&Date.now()/1000>session.expires_at-60){const r=await fetch(config.url+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:config.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});const v=await r.json();if(!r.ok){session=null;localStorage.removeItem('river.session');renderLogin();throw Error('Sua sessão expirou. Entre novamente.')}session={...v,expires_at:v.expires_at||Math.floor(Date.now()/1000)+v.expires_in};localStorage.setItem('river.session',JSON.stringify(session));}const r=await fetch(config.url+path,{...options,headers:{apikey:config.key,Authorization:'Bearer '+(session?.access_token||config.key),'Content-Type':'application/json',...options.headers}});if(r.status===204)return null;const v=await r.json().catch(()=>({}));if(!r.ok)throw Error(v.msg||v.message||v.error_description||v.error||'Não foi possível concluir a operação.');return v}
async function load(){const profile=await api('/rest/v1/profiles?id=eq.'+session.user.id+'&select=*');user=profile[0];if(!user?.active){await logout();throw Error('Seu acesso está bloqueado ou ainda não foi configurado.')}const tables=Object.keys(data);const results=await Promise.all(tables.map(async t=>{let rows=[],offset=0;for(;;){const batch=await api('/rest/v1/'+t+'?select=*&order=id&limit=1000&offset='+offset);rows.push(...batch);if(batch.length<1000)return rows;offset+=1000;}}));tables.forEach((t,i)=>data[t]=results[i]);questionImageUrls={};await Promise.all(data.question_attachments.map(async a=>{try{const s=await api('/storage/v1/object/sign/question-images/'+a.storage_path.split('/').map(encodeURIComponent).join('/'),{method:'POST',body:JSON.stringify({expiresIn:3600})});if(s?.signedURL)questionImageUrls[a.storage_path]=config.url+'/storage/v1'+s.signedURL}catch{}}));}
async function put(table,record,existing=false){for(const k of ['title','name','body','description']){if(typeof record[k]==='string'&&(k!=='description'||table==='questions')&&!record[k].trim())throw Error('Preencha os campos obrigatórios.');}const r=await api('/rest/v1/'+table+(existing?'?id=eq.'+record.id:''),{method:existing?'PATCH':'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(record)});await load();return r?.[0]}
async function uploadQuestionImage(file){if(!file||!file.size)return null;const allowed=['image/jpeg','image/png','image/webp'];if(!allowed.includes(file.type))throw Error('Envie uma imagem JPG, PNG ou WEBP.');if(file.size>10*1024*1024)throw Error('A imagem deve ter no máximo 10 MB.');await api('/auth/v1/user');const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type];const path=user.id+'/'+Date.now()+'-'+crypto.randomUUID()+'.'+ext;const r=await fetch(config.url+'/storage/v1/object/question-images/'+path,{method:'POST',headers:{apikey:config.key,Authorization:'Bearer '+session.access_token,'Content-Type':file.type,'x-upsert':'false'},body:file});if(!r.ok){const e=await r.json().catch(()=>({}));throw Error(e.message||e.error||'Não foi possível enviar a imagem.')}return path}
