function renderLogin(){document.title='Entrar — CPT';$('#app').innerHTML=`<div class="login"><section class="login-visual"><div class="brand"><img class="brand-badge" src="data:image/png;base64," alt="Emblema Careca Poker Team"><div class="brand-name">CPT<small>CARECA POKER TEAM</small></div></div><div class="hero-art"><div class="orbit"></div><span class="art-star">✧</span><div class="playing">A<b>♠</b><small>A</small></div><div class="playing two">K<b>♣</b><small>K</small></div><div class="art-chip"></div></div><h1>Seu próximo nível<br>começa no estudo.</h1><p>Uma biblioteca. Um time. Um espaço para transformar conhecimento em boas decisões.</p><div class="eyebrow" style="color:#d7b67e;margin-top:20px">ESTUDE · REVISE · EVOLUA</div></section><section class="login-form"><div><span class="eyebrow">BEM-VINDO À CPT</span><h1>Vamos evoluir juntos.</h1><p>Entre para acessar suas aulas e continuar seus estudos.</p><form id="loginForm" class="fields"><label>E-mail<input type="email" name="email" autocomplete="username" placeholder="seu@email.com" required></label><label>Senha<input type="password" name="password" autocomplete="current-password" placeholder="Sua senha" required></label><div id="loginError" class="error" role="alert"></div><button class="btn" type="submit">Entrar ${ico('arrow')}</button></form><div class="login-role-label">TIPO DE ACESSO</div><div class="login-role" role="group" aria-label="Tipo de acesso"><button type="button" class="role-option selected" data-action="login-role" data-id="student" aria-pressed="true">${ico('users')}<span><b>Aluno</b><small>Acessar aulas e estudos</small></span></button><button type="button" class="role-option" data-action="login-role" data-id="admin" aria-pressed="false">${ico('settings')}<span><b>Administrador</b><small>Gerenciar conteúdo e usuários</small></span></button></div></div></section></div>`;$('#loginForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{if(!config)throw Error('Configuração do Supabase indisponível.');const f=new FormData(e.target);session=null;const v=await api('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})});session={...v,expires_at:v.expires_at||Math.floor(Date.now()/1000)+v.expires_in};localStorage.setItem('river.session',JSON.stringify(session));await load();if(user.role!==loginRole){await logout();throw Error(loginRole==='admin'?'Esta conta não possui acesso de administrador.':'Esta conta é de administrador. Selecione Administrador para entrar.')}page='dashboard';render()}catch(err){$('#loginError')&&($('#loginError').textContent=err.message)}finally{b.disabled=false}}}
function shell(){const nav=[['dashboard','Dashboard'],['lessons','Aulas'],['questions','Dúvidas'],['profile','Meu perfil'],...(admin()?[['users','Usuários']]:[])];return `<div class="shell"><aside class="sidebar"><div class="brand"><img class="brand-badge" src="data:image/png;base64," alt="Emblema Careca Poker Team"><div class="brand-name">CPT<small>CARECA POKER TEAM</small></div></div><div class="nav-label">SEU ESPAÇO DE ESTUDO</div><nav class="nav" aria-label="Menu principal">${nav.map(([key,label])=>`<button data-action="nav" data-id="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${ico(key)}${label}${key==='lessons'?`<span>${data.lessons.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="tip"><strong>✧ Evolua uma decisão por vez.</strong><p>Revise, tire dúvidas e coloque o aprendizado em jogo.</p></div><div class="side-user"><span class="avatar">${initial(user.name)}</span><div><strong>${esc(user.name.split(' ')[0])}</strong><small>${admin()?'Administrador':'Aluno'}</small></div>${iconbtn('logout','logout','','Sair')}</div></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Abrir menu">${ico('menu')}</button><div class="breadcrumb">CPT <span>/</span> <strong style="color:#d6c4ca;font-weight:500">${nav.find(n=>n[0]===page)?.[1]||'Aulas'}</strong></div><div class="top-right"><span class="tag"><i class="dot"></i> ÁREA CPT</span><button class="avatar" data-action="nav" data-id="profile" aria-label="Meu perfil">${initial(user.name)}</button></div></header><div class="content" id="view"></div><nav class="mobile-bottom-nav" aria-label="Navegação mobile">${nav.map(([key,label])=>`<button data-action="nav" data-id="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${ico(key)}<span>${label==='Meu perfil'?'Perfil':label}</span></button>`).join('')}</nav></main></div>`}
