function dashboard(){const watched=data.lessons.filter(l=>progress(l.id)?.watched).length,reviewed=data.lessons.filter(l=>progress(l.id)?.reviewed).length,mine=data.questions.filter(q=>q.user_id===user.id),next=mods().flatMap(m=>lessons(m.id)).find(l=>!progress(l.id)?.watched),latest=[...data.questions].sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,3);return `${title('Olá, '+esc(user.name.split(' ')[0])+' <span style="font-size:25px">☀</span>','Cada sessão de estudo é um passo à frente. Vamos continuar?',`<span class="subtle">${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long'})}</span>`)}<section class="hero"><div><span class="eyebrow">SEU EDGE COMEÇA AQUI</span><h2>Estude com propósito.<br>Jogue com confiança.</h2><p>Explore as aulas, revise os conceitos e evolua junto com o seu time.</p>${btn('Explorar aulas','nav','lessons','lime','arrow')}</div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><span class="art-star">✧</span><div class="playing">A<b>♠</b><small>A</small></div><div class="playing two">K<b>♣</b><small>K</small></div><div class="art-chip"></div></div></section><div class="stats"><article class="stat"><div class="stat-header">Aulas concluídas<span class="iconbox">${ico('lessons')}</span></div><div class="stat-number">${watched} <small>/ ${data.lessons.length} aulas</small></div>${bar(pct(watched,data.lessons.length))}<div class="stat-footer"><strong>${pct(watched,data.lessons.length)}%</strong> da biblioteca concluída</div></article><article class="stat"><div class="stat-header">Revisões feitas<span class="iconbox">${ico('repeat')}</span></div><div class="stat-number">${reviewed} <small>/ ${data.lessons.length} aulas</small></div>${bar(pct(reviewed,data.lessons.length))}<div class="stat-footer"><strong>${pct(reviewed,data.lessons.length)}%</strong> das aulas revisadas</div></article><article class="stat"><div class="stat-header">Minhas dúvidas<span class="iconbox">${ico('questions')}</span></div><div class="stat-number">${mine.length} <small>dúvidas criadas</small></div><div class="stat-footer" style="margin-top:18px"><strong>${mine.filter(q=>comments(q.id).length).length} com comentários</strong> · ${mine.filter(q=>!comments(q.id).length).length} sem comentários</div></article></div><div class="grid-two"><section><div class="section-title"><h2>Revisão por módulo</h2><button class="link-btn" data-action="nav" data-id="lessons">Ver módulos ${ico('arrow')}</button></div><div class="panel">${mods().length?mods().map((m,i)=>{const s=moduleStats(m.id);return `<div class="module-row"><div class="module-icon tone${i%4}">${['♠','♣','♦','♥'][i%4]}</div><div class="grow"><strong>${esc(m.title)}</strong><p>${s.reviewed} de ${s.total} aulas revisadas</p>${bar(pct(s.reviewed,s.total))}</div><span class="percent">${pct(s.reviewed,s.total)}%</span></div>`}).join(''):empty('Sua biblioteca começa aqui','Crie o primeiro módulo para organizar as aulas.')}</div></section><section><div class="section-title"><h2>Conversas do time</h2><button class="link-btn" data-action="nav" data-id="questions">Ver todas ${ico('arrow')}</button></div><div class="panel">${latest.length?latest.map(q=>`<article class="question-mini"><button data-action="question" data-id="${q.id}" style="padding:0;text-align:left"><h3>${esc(q.title)}</h3></button><div class="mini-meta">${esc(fullname(q.user_id))} <span>·</span> ${esc(moduleName(q.module_id))}</div><div class="mini-foot"><span class="status ${q.resolved?'':'pending'}">${q.resolved?'Resolvida':'Em discussão'}</span><span class="muted">${comments(q.id).length} comentários</span></div></article>`).join(''):empty('Vamos conversar?','Compartilhe sua primeira dúvida com o time.')}</div></section></div>${next?`<div class="continue-card"><div class="thumb"><div class="play-circle">${ico('play')}</div></div><div class="grow"><div class="eyebrow">SEU PRÓXIMO PASSO</div><h3>${esc(next.title)}</h3><p>${esc(moduleName(next.module_id))} · ${next.duration_minutes?next.duration_minutes+' min':'Duração não informada'}</p></div>${btn('Ir para a aula','lesson',next.id,'','arrow')}</div>`:''}<div class="footer-note"><span>CPT · Careca Poker Team · conhecimento que vira jogo.</span><span>Estude. Revise. Evolua.</span></div>`}
function lessonPage(){if(selectedLesson)return playerPage();if(selectedModule){const m=data.modules.find(m=>m.id===selectedModule);if(!m){selectedModule=null;return lessonPage()}return `<button class="back" data-action="modules">${ico('back')} Todos os módulos</button>${title(esc(m.title),esc(m.description||'Suas aulas neste módulo.'),admin()?btn('Adicionar aula','new-lesson',m.id,'','plus'):'')}<div class="lesson-list">${lessons(m.id).map(l=>`<article class="lesson-row"><div class="lesson-num">${progress(l.id)?.watched?ico('check'):String(l.position).padStart(2,'0')}</div><div class="grow"><h3>${esc(l.title)}</h3><p>${l.duration_minutes?l.duration_minutes+' min':'Duração não informada'} · ${progress(l.id)?.reviewed?'Revisada':progress(l.id)?.watched?'Concluída':'Ainda não concluída'}</p></div>${admin()?iconbtn('edit','edit-lesson',l.id,'Editar aula'):''}${btn('Assistir','lesson',l.id,'secondary','play')}</article>`).join('')||empty('Nenhuma aula neste módulo','O administrador pode adicionar a primeira aula.')}</div>`}return `${title('Sua biblioteca de aulas','Uma base sólida para decisões cada vez melhores.',admin()?btn('Adicionar módulo','new-module','','','plus'):'')}<div class="toolbar"><div class="search">${ico('search')}<input id="search" type="search" placeholder="Buscar módulo ou aula..." value="${attr(query)}" aria-label="Buscar módulo ou aula"></div><span class="subtle">${data.modules.length} módulos · ${data.lessons.length} aulas</span></div><div class="module-grid">${mods().filter(m=>(m.title+' '+lessons(m.id).map(l=>l.title).join(' ')).toLowerCase().includes(query.toLowerCase())).map((m,i)=>{const s=moduleStats(m.id);return `<article class="module-card"><div class="module-cover tone${i%4}"><span class="eyebrow">MÓDULO ${String(m.position).padStart(2,'0')}</span><span class="suit" aria-hidden="true">${['♠','♣','♦','♥'][i%4]}</span></div><div class="module-body"><h2>${esc(m.title)}</h2><p>${esc(m.description||'Explore as aulas deste módulo.')}</p><div class="module-meta"><span>${s.total} aulas</span><span>${pct(s.watched,s.total)}% concluído</span></div>${bar(pct(s.watched,s.total))}<div class="module-action">${btn('Explorar módulo','module',m.id,'secondary','arrow')}${admin()?iconbtn('edit','edit-module',m.id,'Editar módulo'):''}</div></div></article>`}).join('')}</div>${!data.modules.length?empty('Ainda não há módulos','O administrador pode criar os módulos e adicionar as aulas.'):''}`}
function driveUrl(value){if(!value)return null;try{const u=new URL(value);if(u.protocol!=='https:'||!['drive.google.com','docs.google.com'].includes(u.hostname))return null;const match=u.pathname.match(/\/file\/d\/([A-Za-z0-9_-]+)/);const id=match?.[1]||u.searchParams.get('id');return id&&/^[\w-]{10,}$/.test(id)?'https://drive.google.com/file/d/'+id+'/preview':null}catch{return null}}
function video(url){const src=driveUrl(url);return `<div class="player">${src?`<iframe src="${attr(src)}" title="Player de vídeo do Google Drive" allow="autoplay; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`:`<div class="player-empty">${ico('play')}<h3>O conteúdo começa aqui.</h3><p>O vídeo desta aula ainda não foi adicionado.</p></div>`}</div>`}
function playerPage(){const l=data.lessons.find(l=>l.id===selectedLesson);if(!l){selectedLesson=null;return lessonPage()}const p=progress(l.id),ls=lessons(l.module_id),feed=lessonComments(l.id).sort((a,b)=>a.created_at.localeCompare(b.created_at));return `<button class="back" data-action="module" data-id="${l.module_id}">${ico('back')} ${esc(moduleName(l.module_id))}</button><div class="player-grid"><section>${video(l.video_url)}<div class="player-info"><span class="eyebrow muted">${esc(moduleName(l.module_id))} · AULA ${l.position}</span><h1 style="margin-top:12px">${esc(l.title)}</h1><p class="muted" style="white-space:pre-wrap">${esc(l.description||'')}</p>${l.video_url?'<p class="subtle">Se o vídeo não carregar, confira a permissão de compartilhamento no Google Drive.</p>':''}<div class="player-actions">${btn(p?.watched?'Aula concluída':'Marcar como concluída','complete',l.id,p?.watched?'secondary':'','check')}${btn(p?.reviewed?'Revisão feita':'Marcar revisão feita','review',l.id,'secondary','repeat')}${admin()?iconbtn('edit','edit-lesson',l.id,'Editar aula'):''}</div><p class="subtle">A conclusão e a revisão são marcadas por você.</p></div><div class="panel lesson-comments"><div class="lesson-comments-head"><div><span class="eyebrow">CONVERSA DA AULA</span><h2>Comentários <span class="muted">(${feed.length})</span></h2></div></div><form id="lessonCommentForm" class="social-comment-form"><span class="avatar">${initial(user.name)}</span><div class="social-comment-input"><textarea name="body" maxlength="5000" required rows="2" placeholder="Escreva um comentário sobre esta aula..."></textarea><div><button class="btn" type="submit">Enviar ${ico('arrow')}</button></div></div></form><div class="lesson-comment-feed">${feed.map(c=>`<div class="comment social-comment"><span class="avatar">${initial(fullname(c.user_id))}</span><div class="grow"><div class="comment-author"><strong>${esc(fullname(c.user_id))}</strong><small>· ${date(c.created_at)}</small></div><p>${esc(c.body)}</p></div>${c.user_id===user.id||admin()?iconbtn('trash','delete-comment',c.id,'Excluir comentário'):''}</div>`).join('')||'<div class="comment-empty"><p>Ainda não há comentários nesta aula.</p><small>Seja o primeiro a iniciar a conversa.</small></div>'}</div></div></section><aside class="panel playlist"><h3>Aulas do módulo</h3><p class="subtle">${moduleStats(l.module_id).watched} de ${ls.length} concluídas</p>${ls.map(x=>`<button data-action="lesson" data-id="${x.id}" class="${x.id===l.id?'active':''}">${ico(progress(x.id)?.watched?'check':'play')}<span>${esc(x.title)}</span></button>`).join('')}</aside></div>`}
function questionsPage(){if(selectedQuestion)return questionDetail();let rows=[...data.questions].sort((a,b)=>b.created_at.localeCompare(a.created_at)).filter(q=>(q.title+' '+q.description).toLowerCase().includes(query.toLowerCase())&&(filter==='all'||(filter==='mine'?q.user_id===user.id:!q.resolved)));return `${title('Dúvidas do time','Boas perguntas abrem caminho para boas decisões.',btn('Adicionar dúvida','new-question','','','plus'))}<div class="toolbar"><div class="search">${ico('search')}<input id="search" type="search" placeholder="Buscar uma dúvida..." value="${attr(query)}" aria-label="Buscar dúvida"></div><div class="tabs">${[['all','Todas'],['mine','Minhas dúvidas'],['open','Em discussão']].map(([id,label])=>`<button data-action="filter" data-id="${id}" class="${filter===id?'active':''}">${label}</button>`).join('')}</div></div><div class="question-list">${rows.map(q=>`<article class="question-card"><span class="avatar">${initial(fullname(q.user_id))}</span><div class="grow"><button data-action="question" data-id="${q.id}" style="padding:0;text-align:left"><h3>${esc(q.title)}</h3></button><div class="meta"><span>${esc(fullname(q.user_id))}</span><span>${date(q.created_at)}</span><span>${esc(moduleName(q.module_id))}</span></div><p>${esc(q.description)}</p><div class="bottom"><span class="status ${q.resolved?'':'pending'}">${q.resolved?'Resolvida':'Em discussão'}</span><button class="link-btn" data-action="question" data-id="${q.id}">${ico('questions')}${comments(q.id).length} comentários ${ico('arrow')}</button></div></div></article>`).join('')||empty('Nenhuma dúvida por aqui','Crie uma dúvida ou tente outra busca.')}</div>`}
function questionDetail(){const q=data.questions.find(q=>q.id===selectedQuestion);if(!q){selectedQuestion=null;return questionsPage()}const owns=q.user_id===user.id||admin();return `<button class="back" data-action="questions">${ico('back')} Todas as dúvidas</button>${title(esc(q.title),esc(fullname(q.user_id))+' · '+esc(moduleName(q.module_id))+' · '+date(q.created_at),owns?iconbtn('edit','edit-question',q.id,'Editar dúvida'):'')}<div class="player-grid"><section>${q.video_url?video(q.video_url):''}${q.image_path&&questionImageUrls[q.id]?`<div class="question-image"><img src="${attr(questionImageUrls[q.id])}" alt="Imagem anexada à dúvida" loading="lazy"></div>`:''}<div class="panel" style="margin-top:${q.video_url||q.image_path?'20':'0'}px"><span class="status ${q.resolved?'':'pending'}">${q.resolved?'Resolvida':'Em discussão'}</span><p style="white-space:pre-wrap">${esc(q.description)}</p>${owns?btn(q.resolved?'Reabrir dúvida':'Marcar como resolvida','resolve',q.id,'secondary','check'):''}</div><div class="panel" style="margin-top:20px"><h2>Comentários <span class="muted" style="font-size:13px">(${comments(q.id).length})</span></h2>${comments(q.id).sort((a,b)=>a.created_at.localeCompare(b.created_at)).map(c=>`<div class="comment"><span class="avatar">${initial(fullname(c.user_id))}</span><div class="grow"><strong style="font-size:12px">${esc(fullname(c.user_id))}</strong> <small>· ${date(c.created_at)}</small><p>${esc(c.body)}</p></div>${c.user_id===user.id||admin()?iconbtn('trash','delete-comment',c.id,'Excluir comentário'):''}</div>`).join('')||'<p class="subtle">Seja o primeiro a contribuir com essa conversa.</p>'}<form id="commentForm" class="fields" style="margin-top:20px"><label>Seu comentário<textarea name="body" maxlength="5000" required placeholder="Compartilhe sua análise com o time..."></textarea></label><div style="text-align:right"><button class="btn">Publicar comentário ${ico('arrow')}</button></div></form></div></section><aside class="panel" style="height:fit-content"><h3>Um espaço para aprender</h3><p class="subtle">Traga contexto, explique seu raciocínio e ajude o time a construir boas respostas.</p><p class="subtle">Módulo relacionado</p><strong>${esc(moduleName(q.module_id))}</strong></aside></div>`}
function profilePage(){return `${title('Meu perfil','Seu espaço, seu progresso.')}<div class="profile-grid"><aside class="panel profile-summary"><div class="avatar">${initial(user.name)}</div><h2>${esc(user.name)}</h2><p>${esc(user.email)}</p><span class="tag">${admin()?'Administrador':'Aluno'}</span><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><p>${data.lessons.filter(l=>progress(l.id)?.watched).length} aulas concluídas<br>${data.questions.filter(q=>q.user_id===user.id).length} dúvidas compartilhadas</p>${btn('Sair da conta','logout','','secondary','logout')}</aside><section><div class="panel"><h2 style="margin-bottom:24px">Informações pessoais</h2><form id="profileForm" class="fields"><label>Nome<input name="name" value="${attr(user.name)}" required maxlength="100"></label><label>E-mail<input type="email" value="${attr(user.email)}" disabled><small>O e-mail é gerenciado pelo administrador.</small></label><div class="form-actions"><button class="btn">Salvar alterações</button></div></form></div><div class="panel" style="margin-top:20px"><h2 style="margin-bottom:20px">Alterar senha</h2><form id="passwordForm" class="fields"><label>Nova senha<input type="password" name="password" minlength="8" autocomplete="new-password" required></label><label>Confirme a nova senha<input type="password" name="confirm" minlength="8" autocomplete="new-password" required></label><div class="form-actions"><button class="btn secondary">Atualizar senha</button></div></form></div></section></div>`}
function usersPage(){if(!admin())return empty('Acesso restrito','Esta página é exclusiva do administrador.');return `${title('Usuários','Gerencie quem estuda com o seu time.',btn('Adicionar usuário','new-user','','','plus'))}<div class="table-wrap"><table><thead><tr><th>Usuário</th><th>Acesso</th><th>Aulas concluídas</th><th>Status</th><th>Ações</th></tr></thead><tbody>${data.profiles.map(u=>`<tr><td><div class="usercell"><span class="avatar">${initial(u.name)}</span><div><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></div></div></td><td>${u.role==='admin'?'Administrador':'Aluno'}</td><td>${data.lesson_progress.filter(p=>p.user_id===u.id&&p.watched).length} / ${data.lessons.length}</td><td><span class="status ${u.active?'':'pending'}">${u.active?'Ativo':'Bloqueado'}</span></td><td>${u.id!==user.id&&u.role!=='admin'?`<div style="display:flex;gap:8px;align-items:center">${btn(u.active?'Bloquear':'Desbloquear','toggle-user',u.id,'secondary')}${btn('Excluir','delete-user',u.id,'danger','trash')}</div>`: '<span class="subtle">Administrador</span>'}</td></tr>`).join('')}</tbody></table></div>`}
function render(){if(!user)return renderLogin();document.title=({dashboard:'Dashboard',lessons:'Aulas',questions:'Dúvidas',profile:'Meu perfil',users:'Usuários'}[page]||'CPT')+' — CPT';$('#app').innerHTML=shell();renderView()}
function renderView(){if(!$('#view'))return;$('#view').innerHTML=({dashboard,lessons:lessonPage,questions:questionsPage,profile:profilePage,users:usersPage}[page]||dashboard)();const search=$('#search');if(search)search.oninput=e=>{const at=e.target.selectionStart;query=e.target.value;renderView();$('#search').focus();$('#search').setSelectionRange(at,at)};bindForm('#commentForm',async f=>{await put('comments',{question_id:selectedQuestion,user_id:user.id,body:f.get('body').trim(),created_at:new Date().toISOString()});toast('Comentário publicado.');renderView()});bindForm('#lessonCommentForm',async f=>{await put('comments',{lesson_id:selectedLesson,user_id:user.id,body:f.get('body').trim(),created_at:new Date().toISOString()});toast('Comentário publicado.');renderView()});bindForm('#profileForm',async f=>{const name=f.get('name').trim();if(!name)throw Error('Informe seu nome.');await put('profiles',{id:user.id,name},true);user=data.profiles.find(p=>p.id===user.id);toast('Perfil atualizado.');render()});bindForm('#passwordForm',async f=>{if(f.get('password')!==f.get('confirm'))throw Error('As senhas não coincidem.');await api('/auth/v1/user',{method:'PUT',body:JSON.stringify({password:f.get('password')})});toast('Senha atualizada.');$('#passwordForm').reset()})}
function bindForm(selector,handler){const el=$(selector);if(!el)return;el.onsubmit=async e=>{e.preventDefault();const b=el.querySelector('button[type="submit"],button.btn');if(b.disabled)return;b.disabled=true;try{await handler(new FormData(el))}catch(err){toast(err.message)}finally{b.disabled=false}}}
function openModal(title,body,submit,handler,extra=''){const d=$('#modal');d.innerHTML=`<div class="modal-heading"><h2>${title}</h2>${iconbtn('close','close','','Fechar')}</div><form id="modalForm"><div class="fields">${body}</div><div id="modalError" class="error" role="alert"></div><div class="form-actions">${extra}<button type="button" class="btn secondary" data-action="close">Cancelar</button>${submit?'<button type="submit" class="btn">'+submit+'</button>':''}</div></form>`;if(!d.open)d.showModal();$('#modalForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button[type="submit"]');if(b?.disabled)return;if(b)b.disabled=true;try{await handler(new FormData(e.target));d.close();render()}catch(err){$('#modalError').textContent=err.message}finally{if(b)b.disabled=false}}}
const field=(label,name,value='',type='text',required=true,extra='')=>`<label>${label}<input type="${type}" name="${name}" value="${attr(value)}" ${required?'required':''} ${extra}></label>`;
function moduleForm(id){if(!admin())return;const m=data.modules.find(m=>m.id===id);openModal(m?'Editar módulo':'Adicionar módulo',field('Nome do módulo','title',m?.title||'','text',true,'maxlength="120"')+`<label>Descrição<textarea name="description" maxlength="2000">${esc(m?.description||'')}</textarea></label>`+field('Ordem de exibição','position',m?.position||Math.max(0,...data.modules.map(m=>m.position))+1,'number',true,'min="1" max="999"'),m?'Salvar alterações':'Criar módulo',async f=>{await put('modules',{...(m?{id}:{}),title:f.get('title').trim(),description:f.get('description').trim(),position:Number(f.get('position'))},!!m);toast('Módulo salvo.')},m?`<button type="button" class="btn danger" data-action="delete-module" data-id="${id}">Excluir</button>`:'')}
function lessonForm(id,moduleId){if(!admin())return;const l=data.lessons.find(l=>l.id===id);openModal(l?'Editar aula':'Adicionar aula',`<label>Módulo<select name="module_id" required>${mods().map(m=>`<option value="${m.id}" ${(l?.module_id||moduleId)===m.id?'selected':''}>${esc(m.title)}</option>`).join('')}</select></label>`+field('Nome da aula','title',l?.title||'','text',true,'maxlength="160"')+field('Link do vídeo no Google Drive','video_url',l?.video_url||'','url',true)+`<label><small>Use o link de compartilhamento de um arquivo de vídeo. Os alunos precisam ter permissão para acessá-lo no Drive.</small></label><label>Descrição<textarea name="description" maxlength="5000">${esc(l?.description||'')}</textarea></label>`+field('Duração em minutos (opcional)','duration_minutes',l?.duration_minutes||'','number',false,'min="1" max="1440"')+field('Ordem da aula','position',l?.position||Math.max(0,...lessons(moduleId).map(l=>l.position))+1,'number',true,'min="1" max="999"'),l?'Salvar alterações':'Criar aula',async f=>{const url=f.get('video_url').trim();if(url&&!driveUrl(url))throw Error('Informe um link válido de arquivo do Google Drive.');await put('lessons',{...(l?{id}:{}),module_id:f.get('module_id'),title:f.get('title').trim(),video_url:url,description:f.get('description').trim(),duration_minutes:f.get('duration_minutes')?Number(f.get('duration_minutes')):null,position:Number(f.get('position'))},!!l);toast('Aula salva.')},l?`<button type="button" class="btn danger" data-action="delete-lesson" data-id="${id}">Excluir</button>`:'')}
function questionForm(id,moduleId){
 const q=data.questions.find(q=>q.id===id);
 if(q&&q.user_id!==user.id&&!admin())return;
 let selectedFiles=[],removedIds=[];
 const existing=q?data.question_attachments.filter(a=>a.question_id===q.id).sort((a,b)=>a.position-b.position):[];
 const body=field('Título','title',q?.title||'','text',true,'maxlength="180"')+
 `<label>Módulo relacionado<select name="module_id"><option value="">Geral</option>${mods().map(m=>`<option value="${m.id}" ${(q?.module_id||moduleId)===m.id?'selected':''}>${esc(m.title)}</option>`).join('')}</select></label>`+
 field('Link do vídeo no Google Drive (opcional)','video_url',q?.video_url||'','url',false)+
 `<label>Imagens ou prints (opcional)<input id="questionImagesInput" type="file" name="images" accept="image/jpeg,image/png,image/webp" multiple><small>Até 10 imagens · JPG, PNG ou WEBP · máximo 10 MB cada</small></label><div id="questionUploadPreview"></div><label>Descrição<textarea name="description" required maxlength="10000" placeholder="Explique a situação e o que você gostaria de discutir...">${esc(q?.description||'')}</textarea></label>`;
 openModal(q?'Editar dúvida':'Adicionar dúvida',body,q?'Salvar alterações':'Publicar dúvida',async f=>{
  const url=f.get('video_url').trim();
  if(url&&!driveUrl(url))throw Error('Informe um link válido de arquivo do Google Drive.');
  const kept=existing.filter(a=>!removedIds.includes(a.id));
  if(kept.length+selectedFiles.length>10)throw Error('Você pode anexar no máximo 10 imagens.');
  const saved=await put('questions',{...(q?{id}:{user_id:user.id,created_at:new Date().toISOString(),resolved:false}),title:f.get('title').trim(),description:f.get('description').trim(),module_id:f.get('module_id')||null,video_url:url||'',image_path:null},!!q);
  const questionId=q?.id||saved?.id;
  for(const rid of removedIds){const a=existing.find(x=>x.id===rid);if(a){await api('/rest/v1/question_attachments?id=eq.'+rid,{method:'DELETE'});await deleteQuestionImage(a.storage_path)}}
  let pos=kept.length;
  const uploaded=[];
  try{
   for(const file of selectedFiles){
    const path=await uploadQuestionImage(file);uploaded.push(path);pos++;
    await api('/rest/v1/question_attachments',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({question_id:questionId,user_id:user.id,storage_path:path,position:pos})});
   }
  }catch(err){for(const path of uploaded)await deleteQuestionImage(path);throw err}
  await load();toast('Dúvida salva.');
 },q?`<button type="button" class="btn danger" data-action="delete-question" data-id="${id}">Excluir</button>`:'');
 const input=$('#questionImagesInput'),preview=$('#questionUploadPreview'),dialog=$('#modal');
 const draw=()=>{
  const kept=existing.filter(a=>!removedIds.includes(a.id));
  const total=kept.length+selectedFiles.length;
  dialog?.classList.toggle('has-images',total>0);
  if(!preview)return;
  if(!total){preview.innerHTML='';return}
  const items=[
   ...kept.map(a=>({kind:'existing',id:a.id,url:questionImageUrls[a.storage_path],name:'Imagem anexada'})),
   ...selectedFiles.map((file,i)=>({kind:'new',id:i,url:URL.createObjectURL(file),name:file.name}))
  ];
  preview.innerHTML=`<div class="attachment-preview-head"><strong>${total} ${total===1?'imagem':'imagens'}</strong><span>Navegue pelos anexos</span></div><div class="attachment-carousel form-carousel">${items.map((x,i)=>`<figure class="attachment-slide"><img src="${attr(x.url||'')}" alt="${attr(x.name)}"><figcaption><span>${i+1} / ${total}</span><button type="button" class="attachment-remove" data-kind="${x.kind}" data-remove="${x.id}">Remover</button></figcaption></figure>`).join('')}</div>${total>1?'<div class="attachment-nav"><button type="button" data-carousel="-1">‹</button><span>Deslize ou use as setas</span><button type="button" data-carousel="1">›</button></div>':''}`;
  preview.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(b.dataset.kind==='existing')removedIds.push(b.dataset.remove);else selectedFiles.splice(Number(b.dataset.remove),1);draw()});
  preview.querySelectorAll('[data-carousel]').forEach(b=>b.onclick=()=>preview.querySelector('.attachment-carousel')?.scrollBy({left:Number(b.dataset.carousel)*Math.max(280,preview.clientWidth*.72),behavior:'smooth'}));
 };
 if(input)input.onchange=()=>{
  const files=[...input.files];
  for(const file of files){if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Use somente JPG, PNG ou WEBP.');continue}if(file.size>10*1024*1024){toast(file.name+' excede 10 MB.');continue}selectedFiles.push(file)}
  if(existing.filter(a=>!removedIds.includes(a.id)).length+selectedFiles.length>10){selectedFiles=selectedFiles.slice(0,Math.max(0,10-existing.filter(a=>!removedIds.includes(a.id)).length));toast('Limite de 10 imagens por dúvida.')}
  input.value='';draw()
 };
 draw()
}
function confirmDelete(table,id){const names={modules:'módulo e suas aulas',lessons:'aula e seu progresso',questions:'dúvida e seus comentários',comments:'comentário'};openModal('Confirmar exclusão',`<p>Deseja excluir este ${names[table]}? Esta ação não pode ser desfeita.</p>`,'Excluir',async()=>{await remove(table,id);toast('Excluído.');if(table==='lessons')selectedLesson=null;if(table==='modules')selectedModule=null;if(table==='questions')selectedQuestion=null})}
async function setProgress(id,kind){const old=progress(id),watched=kind==='watched'?!old?.watched:(old?.watched||false),reviewed=kind==='reviewed'?!old?.reviewed:(watched?old?.reviewed||false:false);if(kind==='reviewed'&&reviewed&&!watched)throw Error('Conclua a aula antes de marcar uma revisão.');const record={user_id:user.id,lesson_id:id,watched,reviewed,completed_at:watched?(old?.completed_at||new Date().toISOString()):null,reviewed_at:reviewed?new Date().toISOString():null};{await api('/rest/v1/lesson_progress?on_conflict=user_id,lesson_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates'},body:JSON.stringify(record)});await load()}renderView();toast(kind==='watched'?(watched?'Aula concluída. Bom estudo!':'Conclusão removida.'):(reviewed?'Revisão registrada.':'Revisão removida.'))}
function userForm(){if(!admin())return;openModal('Adicionar usuário',field('Nome','name','','text',true,'maxlength="100"')+field('E-mail','email','','email')+field('Senha temporária (mínimo 8 caracteres)','password','','password',true,'minlength="8" autocomplete="new-password"'),'Criar usuário',async f=>{await api('/functions/v1/manage-users',{method:'POST',body:JSON.stringify({action:'create',name:f.get('name').trim(),email:f.get('email'),password:f.get('password')})});await load();toast('Usuário criado.')})}
function deleteUserConfirmation(id){
 if(!admin())return;
 const target=data.profiles.find(p=>p.id===id);
 if(!target||target.id===user.id||target.role==='admin')return;
 openModal('Excluir usuário',`<p>Excluir a conta de <strong>${esc(target.name)}</strong> (${esc(target.email)})?</p><div class="notice">O acesso, o progresso, as dúvidas e os comentários deste aluno serão excluídos permanentemente. Comentários de outros usuários nas dúvidas dele também serão removidos. Esta ação não pode ser desfeita.</div>`,'Excluir usuário',async()=>{
  if(!admin()||target.id===user.id||target.role==='admin')throw Error('Esta conta não pode ser excluída.');
   await api('/functions/v1/manage-users',{method:'POST',body:JSON.stringify({action:'delete',user_id:id})});
   await load();

  toast('Usuário excluído.');
 });
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,id=b.dataset.id;try{switch(action){case 'close':$('#modal').close();break;case 'menu':$('.sidebar').classList.toggle('open');break;case 'nav':page=id;query='';selectedLesson=null;selectedModule=null;selectedQuestion=null;render();break;case 'login-role':loginRole=id;document.querySelectorAll('.role-option').forEach(x=>{const on=x.dataset.id===id;x.classList.toggle('selected',on);x.setAttribute('aria-pressed',on?'true':'false')});break;case 'logout':await logout();break;case 'modules':selectedModule=null;selectedLesson=null;render();break;case 'module':page='lessons';selectedModule=id;selectedLesson=null;query='';render();break;case 'lesson':page='lessons';selectedLesson=id;render();break;case 'questions':selectedQuestion=null;render();break;case 'question':page='questions';selectedQuestion=id;render();break;case 'filter':filter=id;renderView();break;case 'new-module':moduleForm();break;case 'edit-module':moduleForm(id);break;case 'new-lesson':lessonForm(null,id);break;case 'edit-lesson':lessonForm(id);break;case 'new-question':questionForm(null,id);break;case 'edit-question':questionForm(id);break;case 'delete-module':confirmDelete('modules',id);break;case 'delete-lesson':confirmDelete('lessons',id);break;case 'delete-question':confirmDelete('questions',id);break;case 'delete-comment':confirmDelete('comments',id);break;case 'complete':if(busy)return;busy=true;await setProgress(id,'watched');break;case 'review':if(busy)return;busy=true;await setProgress(id,'reviewed');break;case 'resolve':{const q=data.questions.find(q=>q.id===id);if(!q||q.user_id!==user.id&&!admin())return;await put('questions',{id,resolved:!q.resolved},true);renderView();toast('Status atualizado.');break}case 'new-user':userForm();break;case 'delete-user':deleteUserConfirmation(id);break;case 'toggle-user':{if(!admin())return;const p=data.profiles.find(p=>p.id===id);if(!p||p.id===user.id||p.role==='admin')return;{await api('/functions/v1/manage-users',{method:'POST',body:JSON.stringify({action:'set_active',user_id:id,active:!p.active})});await load()}render();toast('Acesso atualizado.');break}}}catch(err){toast(err.message)}finally{busy=false}});
(async()=>{if(session){$('#app').innerHTML='<div class="loading">Preparando seu espaço de estudo…</div>';try{await load();render()}catch(err){renderLogin();toast(err.message)}}else renderLogin()})();